void ProjectPersistence::restore_managed_version(const std::string& current_state, const std::string& selected_state,
                                                  const std::string& from_version, const std::string& selected_version)
{
    ProjectStateDocument current;
    ProjectStateDocument selected;
    if (current.load(current_state) == ProjectStateDocument::LoadResult::Corrupt ||
        selected.load(selected_state) == ProjectStateDocument::LoadResult::Corrupt ||
        current.project_id().empty() || current.project_id() != selected.project_id())
        throw std::runtime_error("project version has incompatible semantic state");
    current.normalize_interrupted_state();
    current.restore_project_fields(selected);
    ChangeEntry change;
    change.kind = "restore";
    change.actor = "person";
    change.label = "Restored an earlier project version";
    change.from = from_version;
    change.to = selected_version;
    current.add_change(std::move(change), m_config.clock());
    m_document = std::move(current);
    m_draft = m_document.draft();
    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
    m_attached = true;
    m_boundary_pending = false;
    m_dirty = true;
    flush();
    notify_document_replaced();
}

