const r=await tools.exec_command({cmd:"python3 - <<'PY'
import pathlib, subprocess, tempfile
for path in ('src/slic3r/GUI/Plater.cpp', 'src/slic3r/GUI/Plater.hpp'):
    with tempfile.TemporaryDirectory(prefix='jusprin-merge-') as temp:
        files = [pathlib.Path(temp) / name for name in ('upstream','base','current')]
        files[0].write_bytes(subprocess.check_output(['git','show',f'upstream/main:{path}']))
        files[1].write_bytes(subprocess.check_output(['git','show',f'HEAD:{path}']))
        files[2].write_bytes(pathlib.Path(path).read_bytes())
        p = subprocess.run(['git','merge-file','-p',*[str(x) for x in files]],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
        chunks = []
        lines=p.stdout.splitlines()
        for i,line in enumerate(lines):
            if line.startswith('<<<<<<<'):
                end=next((j for j in range(i+1,len(lines)) if lines[j].startswith('>>>>>>>')), min(i+35,len(lines)-1))
                chunks.append('\n'.join(lines[i:min(end+1,i+42)]))
