                      "history_timestamp_click_does_not_restore");
                check(older->row_action_label() == wxGetTranslation("Restore"),
                      "history_older_version_has_restore_button");
                struct RestoreChoice : wxEventFilter {
                    int shown{0};
                    int answer{wxID_NO};
                    int FilterEvent(wxEvent& event) override
                    {
                        if (event.GetEventType() != wxEVT_SHOW || !static_cast<wxShowEvent&>(event).IsShown())
                            return Event_Skip;
                        auto* dialog = dynamic_cast<wxMessageDialog*>(event.GetEventObject());
                        if (!dialog || dialog->GetTitle() != wxGetTranslation("Restore project version"))
                            return Event_Skip;
                        ++shown;
                        dialog->CallAfter([dialog, answer = answer] { dialog->EndModal(answer); });
                        return Event_Skip;
                    }
                } restore_choice;
                wxEvtHandler::AddFilter(&restore_choice);
                older->invoke_row_action();
                wxYield();
                check(restore_choice.shown == 1 && autosave->current_version() == latest &&
                          m_plater->model().objects.size() == objects,
                      "history_restore_cancel_keeps_model");
                installed_shell()->status_row()->show_version_history();
                menu = visible_header_menu();
                older = menu ? dynamic_cast<HeaderButton*>(wxWindow::FindWindowByName(
                    wxString::FromUTF8(versions[versions.size() - 2].created_at), menu)) : nullptr;
                const bool restore_button_found = older != nullptr;
                if (restore_button_found) {
                    restore_choice.answer = wxID_YES;
                    older->invoke_row_action();
                    wxYield();
                }
                wxEvtHandler::RemoveFilter(&restore_choice);
                check(restore_button_found && restore_choice.shown == 2 &&
                          m_plater->model().objects.size() == versions[versions.size() - 2].objects.size(),
                      "history_restore_confirm_reloads_older_model");
            }
        }
        finish();
    }

    // Counts every dialog that becomes visible, other than the load progress
    // window, while it is installed.
    struct DialogCounter : wxEventFilter
    {
        int  shown = 0;
        std::vector<std::string> titles;
"}

