void StatusRow::show_version_history(std::size_t offset)
{
    if (m_autosave == nullptr)
        return;
    try {
        if (!m_autosave->save_now())
            throw std::runtime_error(m_autosave->error());
        const auto versions = m_autosave->history();
        const std::string current = m_autosave->current_version();
        std::vector<HeaderMenuItem> menu{
            {_L("Local project versions"),HeaderIcon::None,{},false,false,{}},
            {_L("Back"),HeaderIcon::Back,{},true,false,[this] { show_overflow_menu(); }}
        };
        const std::size_t end = std::min(versions.size(), offset + 8);
        for (std::size_t index = offset; index < end; ++index) {
            const auto& version = versions[versions.size() - 1 - index];
            wxString label = wxString::FromUTF8(version.created_at);
            if (version.id == current)
                label += _L(" (current)");
            HeaderMenuItem item;
            item.label = label;
            item.enabled = version.id != current;
            item.row_action_label = version.id == current ? wxString() : _L("Restore");
            item.dismisses_on_row_action = true;
            item.invoke_row_action = [this, id = version.id] {
                const bool confirmed = m_restore_confirmation ? m_restore_confirmation() : [this] {
                    wxMessageDialog confirmation(this,
                        _L("Restore this version of the model and project settings? The current model will be saved "
                           "as a version first. Conversations and print records will stay current."),
                        _L("Restore project version"), wxYES_NO | wxICON_QUESTION);
                    confirmation.SetYesNoLabels(_L("Restore"), _L("Cancel"));
                    return confirmation.ShowModal() == wxID_YES;
                }();
                if (!confirmed)
                    return;
                if (!m_autosave->restore(id))
                    wxMessageBox(wxString::FromUTF8(m_autosave->error()), _L("Restore failed"), wxOK | wxICON_ERROR, this);
                refresh();
            };
            menu.push_back(std::move(item));
        }
        if (end < versions.size())
            menu.push_back({_L("Older versions…"),HeaderIcon::None,{},true,false,[this, end] { show_version_history(end); }});
        (new HeaderMenu(this,m_theme,m_dark,std::move(menu)))->open(*m_overflow_button);
    } catch (const std::exception& error) {
        wxMessageBox(wxString::FromUTF8(error.what()), _L("Version history unavailable"), wxOK | wxICON_ERROR, this);
    }
        return false;
    }
}

std::vector<ProjectAutosave::ManagedProject> ProjectAutosave::projects()
{
    settle(true);
    // Home can be opened before the first project switch. Render the current
    // project once here; the preview is independent of the frequent backups.
    ensure_current_preview();
    std::vector<ManagedProject> result;
    for (const auto& entry : std::filesystem::directory_iterator(m_root)) {
        if (!entry.is_directory() || !std::filesystem::exists(entry.path() / "HEAD"))
            continue;
        try {
            if (!authored_head(entry.path()))
                continue;
            const std::string id = entry.path().filename().string();
            const auto add = [&result, &entry, &id](const ProjectVersionStore::Version& version) {
                const auto source = std::filesystem::u8path(version.source_path);
                std::string name = !version.project_name.empty() ? version.project_name : source.stem().u8string();
                if (name.empty() && !version.objects.empty()) {
                    // Versions written before projectName was added still have
                    // the original object name in their Orca resource entry.
                    const auto& object = version.objects.front();
                    name = std::filesystem::u8path(object.entry).filename().u8string();
                    const std::string suffix = "_" + std::to_string(object.backup_id) + ".model";
                    if (name.size() > suffix.size() && name.compare(name.size() - suffix.size(), suffix.size(), suffix) == 0)
                        name.erase(name.size() - suffix.size());
                    name = std::filesystem::u8path(name).stem().u8string();
                }
                ManagedProject project{id, name, version.created_at, version.source_path, entry.path().u8string()};
                try {
                    project.thumbnail_url = saved_preview(entry.path(), version.id);
                    if (project.thumbnail_url.empty()) {
                        // Older local projects have no preview sidecar. Orca's
                        // original 3MF thumbnail keeps their Home cards useful
                        // until the project is next opened and rendered locally.
                        project.thumbnail_url = source_preview(version.source_path);
                        if (!project.thumbnail_url.empty())
                            write_preview(entry.path(), version.id, project.thumbnail_url);
                    }
                } catch (const std::exception& error) {
                    // A damaged preview must not hide an otherwise healthy
                    // local project from Home.
                    BOOST_LOG_TRIVIAL(warning) << "Local project preview unavailable: " << error.what();
                }
                result.push_back(std::move(project));
            };
            if (m_store && id == m_store->project_id()) {
                const auto versions = m_store->history();
                if (!versions.empty())
                    add(versions.back());
            } else {
