    if (!m_autosave->open_managed_project(project_id)) {
        wxMessageBox(wxString::FromUTF8(m_autosave->error()), _L("Open local project failed"), wxOK | wxICON_ERROR, &m_frame);
        return;
    }
    m_frame.select_tab(size_t(MainFrame::tp3DEditor));
}

