wxString AgentWebView::diagnostics_text(const wxString& reason) const
{
    wxString text = reason;
    text += "\n\n";
    text += _L("This is an internal connection between the application and its Agent panel, not a network service.");
    text += "\n";
    text += wxString::Format("URL: %s", m_page_url.empty() ? wxString(agent_page_path().string()) : m_page_url);
    if (!m_last_load_error.empty())
        text += wxString::Format("\n%s: %s", _L("Last load error"), m_last_load_error);

export function ConnectingPane() {
  return (
    <div className="pane-state" data-testid="connecting">
      <h1>Connecting…</h1>
      <p>Starting the Agent panel.</p>
    </div>
  );
}

export function BridgeErrorPane({ title, detail, diagnostics, onRetry }: BridgeErrorProps) {
  return (
    <div className="pane-state" data-testid="bridge-error" role="alert">
      <h1>{title}</h1>
      <p>This is an internal connection inside JusPrin, not a network service. The 3D canvas and all other controls keep working.</p>
      {detail && <p>{detail}</p>}
      <button className="primary" onClick={onRetry}>
        Retry
      </button>
      <details>
        <summary>Diagnostics</summary>
        <pre>{diagnostics.length > 0 ? diagnostics.join('\n') : 'No bridge messages recorded.'}</pre>
      </details>
    </div>

