+void StatusRow::show_recent_projects(std::size_t offset)
+{
+    if (m_autosave == nullptr)
+        return;
+    try {
+        if (!m_autosave->save_now())
+            throw std::runtime_error(m_autosave->error());
+        const auto projects = m_autosave->projects();
