+                refresh();
+            }});
+        }
+        if (end < projects.size())
+            menu.push_back({_L("Older projects…"),HeaderIcon::None,{},true,false,[this, end] { show_recent_projects(end); }});
+        (new HeaderMenu(this,m_theme,m_dark,std::move(menu)))->open(*m_overflow_button);
